<template><AppLayout><TablePageLayout><template #filters><div class="space-y-3"><div class="flex flex-wrap justify-between gap-4"><div><h1 class="text-2xl font-semibold">{{ t('adminMarketplace.reconciliation') }}</h1><p class="mt-1 text-sm text-gray-500">{{ t('adminMarketplace.reconciliationHint') }}</p></div><div class="flex flex-wrap gap-2"><button class="btn btn-secondary" @click="incidentOpen = true">{{ t('adminMarketplace.executionIncident') }}</button><button class="btn btn-secondary" @click="openTool('migrate')">{{ t('adminMarketplace.migrate') }}</button><button class="btn btn-secondary" @click="openTool('statement')">{{ t('adminMarketplace.statement') }}</button><button class="btn btn-secondary" :disabled="loading" @click="load">{{ t('common.refresh') }}</button></div></div><form class="flex flex-wrap items-end gap-3" @submit.prevent="page = 1; load()"><label class="text-sm">{{ t('adminMarketplace.statusFilter') }}<input v-model="statusFilter" class="input mt-1" /></label><button class="btn btn-secondary" type="submit">{{ t('adminMarketplace.filter') }}</button></form><div v-if="totals" class="grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-5"><StatCard v-for="field in totalFields" :key="field" :title="t(`adminMarketplace.${field}`)" :value="totals[field]" /></div><p v-if="totals" class="text-sm text-gray-500">{{ t('adminMarketplace.receiptStatuses') }}: <span v-for="(count, status) in totals.receipt_statuses" :key="status" class="mr-3">{{ status }}: {{ count }}</span></p><p v-if="error" role="alert" class="text-red-600">{{ error }} <button class="underline" @click="load">{{ t('adminMarketplace.retry') }}</button></p></div></template><template #table><DataTable :columns="columns" :data="rows" :loading="loading"><template #cell-actions="{ row }"><div v-if="row.kind === 'receipt'" class="flex flex-wrap gap-2"><button class="btn btn-secondary btn-sm" @click="openReceipt(row, 'reconcile')">{{ t('adminMarketplace.reconcile') }}</button><button class="btn btn-secondary btn-sm" @click="openReceipt(row, 'refund')">{{ t('adminMarketplace.refund') }}</button></div></template></DataTable></template><template #pagination><Pagination v-if="total > 20" :page="page" :page-size="20" :total="total" @update:page="changePage" /></template></TablePageLayout>
<BaseDialog :show="!!tool" :title="t(`adminMarketplace.${tool || 'reconcile'}`)" @close="close"><div class="space-y-4"><p v-if="tool === 'migrate'">{{ t('adminMarketplace.migrateConfirm') }}</p><p v-if="tool === 'reconcile'" class="rounded-lg bg-amber-50 p-3 text-sm text-amber-900 dark:bg-amber-900/20 dark:text-amber-200">{{ t('adminMarketplace.receiptWarning') }}</p><p v-if="attempted" class="text-sm text-amber-700 dark:text-amber-300">{{ t('adminMarketplace.retrySame') }} <button v-if="receipt" class="underline" :disabled="busy" @click="checkReceipt">{{ t('adminMarketplace.checkStatus') }}</button></p><p v-if="receipt">{{ t('adminMarketplace.receipt') }}: {{ receipt.id }} · {{ receipt.status }}</p><label v-if="tool === 'reconcile'" class="block">{{ t('adminMarketplace.decision') }}<select v-model="form.action" :disabled="attempted" class="input mt-1"><option value="release_confirmed_unexecuted">{{ t('adminMarketplace.release_confirmed_unexecuted') }}</option><option value="retry_known_usage">{{ t('adminMarketplace.retry_known_usage') }}</option></select></label><label v-if="tool === 'refund'" class="block">{{ t('adminMarketplace.amount') }} (USD)<input v-model="form.amount" class="input mt-1" inputmode="decimal" :disabled="attempted" /></label><label v-if="tool === 'migrate' || tool === 'statement'" class="block">{{ t('adminMarketplace.userId') }}<input v-model="form.userId" class="input mt-1" inputmode="numeric" :disabled="attempted" /></label><label v-if="tool === 'statement'" class="block">{{ t('adminMarketplace.month') }} (UTC)<input v-model="form.month" type="month" class="input mt-1" :disabled="attempted" /></label><label v-if="tool !== 'migrate'" class="block">{{ t('adminMarketplace.reason') }}<textarea v-model="form.reason" class="input mt-1" rows="3" :disabled="attempted" /></label><p v-if="dialogError" role="alert" class="text-red-600">{{ dialogError }}</p><div v-if="result" role="status" class="text-sm text-primary-700 dark:text-primary-300"><p>{{ t('adminMarketplace.completed') }}</p><dl v-if="tool === 'migrate'" class="mt-2 grid grid-cols-2 gap-2"><template v-for="field in migrationFields" :key="field"><dt>{{ t(`adminMarketplace.${field}`) }}</dt><dd>{{ result[field] }}</dd></template></dl></div></div><template #footer><button class="btn btn-secondary" :disabled="busy" @click="close">{{ t('common.close') }}</button><button class="btn btn-primary" :disabled="busy || !!result || !valid || (attempted && !!receipt && !statusChecked)" @click="submit">{{ attempted ? t('adminMarketplace.retryAction') : t('adminMarketplace.confirmAction') }}</button></template></BaseDialog><TotpStepUpDialog :controller="stepUp" /><ExecutionIncidentDialog :show="incidentOpen" @close="incidentOpen = false" /></AppLayout></template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import TablePageLayout from '@/components/layout/TablePageLayout.vue'
import DataTable from '@/components/common/DataTable.vue'
import StatCard from '@/components/common/StatCard.vue'
import Pagination from '@/components/common/Pagination.vue'
import BaseDialog from '@/components/common/BaseDialog.vue'
import TotpStepUpDialog from '@/components/auth/TotpStepUpDialog.vue'
import { useStepUp, isStepUpCancelled } from '@/composables/useStepUp'
import { reconciliation, post, type Receipt, type ReconciliationTotals } from '@/api/admin/marketplace'
import ExecutionIncidentDialog from '@/components/marketplace/ExecutionIncidentDialog.vue'
import { validPrice } from './adminState'
const { t } = useI18n(), stepUp = useStepUp()
const incidentOpen = ref(false)
const loading = ref(false), busy = ref(false), error = ref(''), dialogError = ref(''), result = ref<Record<string, any> | null>(null), statusFilter = ref(''), totals = ref<ReconciliationTotals | null>(null), page = ref(1), total = ref(0), rows = ref<Receipt[]>([])
const receipt = ref<Receipt | null>(null), tool = ref(''), attempted = ref(false), statusChecked = ref(false), form = ref({ action: 'release_confirmed_unexecuted', amount: '', userId: '', month: '', reason: '' })
const operations = new Map<string, { key: string; body: any; path: string }>()
const columns = computed(() => ['kind', 'id', 'status', 'difference', 'age_seconds', 'actions'].map(key => ({ key, label: t(`adminMarketplace.${key}`) })))
const valid = computed(() => tool.value === 'migrate' ? /^[1-9]\d*$/.test(form.value.userId) : !!form.value.reason.trim() && (tool.value !== 'refund' || validPrice(form.value.amount)) && (tool.value !== 'statement' || (/^[1-9]\d*$/.test(form.value.userId) && /^\d{4}-(0[1-9]|1[0-2])$/.test(form.value.month))))
const totalFields = ['unbalanced_transactions', 'wallet_differences', 'funding_differences', 'aged_outbox', 'uncertain_payouts'] as const
const migrationFields = ['currency', 'eligible_available', 'reserved', 'excluded_available', 'debt', 'migrated', 'reconciled'] as const
async function load() { loading.value = true; error.value = ''; try { const value = await reconciliation(page.value, statusFilter.value); rows.value = value.items; total.value = value.total; totals.value = value.totals } catch (e: any) { error.value = e?.message || t('adminMarketplace.loadError') } finally { loading.value = false } }
function changePage(next: number) { page.value = next; void load() }
async function checkReceipt() { if (!receipt.value) return; busy.value = true; dialogError.value = ''; try { const current = await reconciliation(page.value, statusFilter.value); const found = current.items.find(row => row.kind === 'receipt' && row.id === receipt.value!.id); if (!found || found.status !== receipt.value.status) { dialogError.value = t('adminMarketplace.receiptChanged'); return } statusChecked.value = true; rows.value = current.items; totals.value = current.totals; total.value = current.total } catch (e: any) { dialogError.value = e?.message || t('adminMarketplace.loadError') } finally { busy.value = false } }
function openReceipt(row: Receipt, next: string) { receipt.value = row; openTool(next) }
function openTool(next: string) { tool.value = next; dialogError.value = ''; result.value = null; form.value = { action: 'release_confirmed_unexecuted', amount: '', userId: '', month: '', reason: '' }; const op = operations.get(`${next}:${receipt.value?.id || ''}`); attempted.value = !!op; statusChecked.value = false; if (op) { const b = op.body; form.value = { action: b.action || 'release_confirmed_unexecuted', amount: b.amount || '', userId: b.supplier_id ? String(b.supplier_id) : op.path.match(/wallets\/(\d+)/)?.[1] || '', month: b.month || '', reason: b.reason || '' } } }
function close() { tool.value = ''; receipt.value = null; dialogError.value = '' }
async function submit() { if (!valid.value || busy.value || result.value) return; const operationId = `${tool.value}:${receipt.value?.id || ''}`; let op = operations.get(operationId); if (!op) { const body = tool.value === 'reconcile' ? { action: form.value.action, reason: form.value.reason.trim() } : tool.value === 'refund' ? { amount: form.value.amount, reason: form.value.reason.trim() } : tool.value === 'statement' ? { supplier_id: Number(form.value.userId), month: form.value.month, reason: form.value.reason.trim() } : {}; const path = tool.value === 'migrate' ? `wallets/${form.value.userId}/migrate` : tool.value === 'statement' ? 'statements/generate' : `receipts/${receipt.value!.id}/${tool.value}`; op = { key: crypto.randomUUID(), body, path }; operations.set(operationId, op) } attempted.value = true; statusChecked.value = false; busy.value = true; dialogError.value = ''; try { const execute = () => post(op!.path, op!.body, op!.key); const response = await stepUp.run(execute); operations.delete(operationId); attempted.value = false; result.value = typeof response === 'object' && response ? response as Record<string, any> : {}; await load() } catch (e: any) { if (!isStepUpCancelled(e)) dialogError.value = e?.message || t('adminMarketplace.actionError') } finally { busy.value = false } }
onMounted(load)
</script>
